input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.5/Brick#>
PREFIX ref: <http://brickexemplarnetworks.org/schema/1.0/ref#>
SELECT ?zone ?zoneid ?temp ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasSubClass* ?z ;
        ref:hasIdentifier ?zoneid .
  OPTIONAL { ?p brick:isTypeOf brick:ZoneTemperature ; ?zone brick:hasPoint ?p ; ?p ref:hasTimeseriesId ?tsid }
}

